from copy import deepcopy
from datetime import datetime, timezone
from importlib import import_module
from typing import Any

from lfx.custom.custom_component.component import Component
from lfx.io import DataInput, MessageTextInput, Output
from lfx.schema.data import Data

TRUNCATED = ("...", "생략", "omitted", "truncated")
DEFAULT_DATABASE = "datagov"
DEFAULT_COLLECTION = "agent_v4_table_catalog_items"
COLLECTION_ENV = "MONGODB_TABLE_CATALOG_COLLECTION"
ALLOWED_SOURCE_CONFIG_KEYS = {
    "source_type", "db_key", "query_template", "api_url", "url", "endpoint", "endpoint_id", "method",
    "headers", "params", "query_params", "body", "payload", "response_path", "doc_id", "sheet_name", "token_source", "token_key",
    "upstream_bindings",
}
SAFE_REFERENCE_KEYS = {"token_source", "token_key"}
SECRET_PATTERNS = ("password", "passwd", "token", "secret", "api_key", "apikey", "authorization", "credential", "access_key", "private_key", "cookie")
QA_SNAPSHOT_CACHE_REGISTRY = "_metadata_driven_v5_qa_snapshot_cache_v1"


# 주요 함수: 결정론적 검증과 duplicate 정책을 적용하고 dry-run 계획 또는 실제 저장을 수행합니다.
# Langflow 클래스와 단위 테스트가 같은 업무 규칙을 쓰도록 일반 Python 값 중심으로 처리합니다.
def review_and_write(payload_value: Any, review_response: Any = "", mongo_uri: str = "", mongo_database: str = "", collection_name: str = "") -> dict[str, Any]:
    payload = _payload(payload_value)
    dry_run = bool(_dict(payload.get("request")).get("dry_run", True))
    action = _duplicate_action(payload)
    payload, partial_update_materialization = _materialize_partial_usage_updates(
        payload, action
    )
    deterministic_errors = _unique_errors(
        _deterministic_errors(payload) + _duplicate_lookup_errors(payload, action)
    )
    llm_review = _json(review_response)
    review = _merge_review(llm_review, payload, deterministic_errors)
    ready = bool(review.get("ready_to_save"))
    next_payload = payload
    next_payload.setdefault("trace", {})[
        "partial_usage_update_materialization"
    ] = partial_update_materialization
    next_payload["review"] = review
    if not ready:
        needs_input = bool(_list(review.get("supplement_requests")))
        next_payload["write_result"] = {
            "success": False,
            "ready_to_save": False,
            "status": "needs_input" if needs_input else "error",
            "saved_count": 0,
            "message": "추가 정보가 필요해 저장하지 않았습니다." if needs_input else "필수 검증을 통과하지 못해 저장하지 않았습니다.",
            "errors": review.get("errors", []),
            "supplement_requests": deepcopy(_list(review.get("supplement_requests"))),
        }
    elif dry_run:
        next_payload["write_result"] = _dry_run_result(payload, action)
    else:
        next_payload["write_result"] = _write_to_mongodb(payload, action, mongo_uri, mongo_database, collection_name)
        if next_payload["write_result"].get("success") and int(next_payload["write_result"].get("saved_count") or 0) > 0:
            next_payload["write_result"]["metadata_qa_snapshot_invalidated"] = _invalidate_metadata_qa_snapshot_cache()
    return next_payload


# 함수 설명: `_materialize_partial_usage_updates()`는 기존 Catalog의 사용 설명만 수정할 때
# 05의 exact-key 조회 결과를 먼저 병합하여, LLM이 만든 빈 SQL/컬럼 skeleton이 실행 계약을 덮지 않게 합니다.
def _materialize_partial_usage_updates(
    payload: dict[str, Any], action: str
) -> tuple[dict[str, Any], dict[str, Any]]:
    next_payload = deepcopy(payload)
    raw_items = next_payload.get("items")
    if not isinstance(raw_items, list):
        return next_payload, {"status": "not_needed", "items": []}

    existing_by_key: dict[str, dict[str, Any]] = {}
    for raw_match in _list(next_payload.get("existing_matches")):
        match = _dict(raw_match)
        key = str(match.get("existing_key") or match.get("new_key") or "").strip()
        existing = _dict(match.get("existing_item"))
        if key and existing:
            existing_by_key[key.casefold()] = existing

    materialized_items: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    details: list[dict[str, Any]] = []
    for raw_item in raw_items:
        if not isinstance(raw_item, dict):
            materialized_items.append(deepcopy(raw_item))
            continue
        item = deepcopy(raw_item)
        marker = item.pop("_partial_update", None)
        if not _is_partial_usage_update_marker(marker):
            materialized_items.append(item)
            continue

        key = str(item.get("dataset_key") or item.get("key") or "").strip()
        existing = existing_by_key.get(key.casefold()) if key else None
        if action != "merge":
            errors.append(
                {
                    "type": "partial_usage_update_requires_merge",
                    "message": "기존 데이터의 사용 설명만 바꾸려면 중복 처리 방식을 merge로 선택해야 합니다.",
                    "key": key,
                }
            )
            materialized_items.append(item)
            continue
        if not existing:
            errors.append(
                {
                    "type": "partial_usage_update_existing_catalog_missing",
                    "message": "기존 데이터의 사용 설명만 바꾸려면 같은 dataset_key의 기존 Table Catalog를 확인해야 합니다.",
                    "key": key,
                }
            )
            materialized_items.append(item)
            continue
        merged = _deep_merge(existing, item)
        merged["dataset_key"] = key
        merged.pop("_partial_update", None)
        materialized_items.append(merged)
        details.append({"dataset_key": key, "fields": ["selection_criteria"]})

    next_payload["items"] = materialized_items
    if errors:
        next_payload.setdefault("errors", []).extend(errors)
    return next_payload, {
        "status": "applied" if details else ("blocked" if errors else "not_needed"),
        "items": details,
        "errors": errors,
    }


# 함수 설명: Table Catalog normalizer가 발행한 좁은 partial update marker만 수용합니다.
def _is_partial_usage_update_marker(value: Any) -> bool:
    return (
        isinstance(value, dict)
        and value.get("reason") == "worker_usage_description"
        and value.get("fields") == ["selection_criteria"]
    )


# 함수 설명: `_invalidate_metadata_qa_snapshot_cache()`는 실제 저장 성공 후 같은 worker의 QA snapshot generation을 증가시킵니다.
def _invalidate_metadata_qa_snapshot_cache() -> bool:
    registry = getattr(builtins, QA_SNAPSHOT_CACHE_REGISTRY, None)
    if not isinstance(registry, dict):
        registry = {"generation": 0, "entries": {}}
        setattr(builtins, QA_SNAPSHOT_CACHE_REGISTRY, registry)
    try:
        registry["generation"] = max(0, int(registry.get("generation", 0))) + 1
    except Exception:
        registry["generation"] = 1
    registry["entries"] = {}
    return True


# 함수 설명: `_deterministic_errors()`는 저장 후보의 필수 필드·허용값·비밀값 위반을 중복 없는 오류 목록으로 만듭니다.
def _deterministic_errors(payload: dict[str, Any]) -> list[dict[str, Any]]:
    errors = _unique_errors(deepcopy(_list(payload.get("errors"))))
    for item in payload.get("items", []):
        if not isinstance(item, dict):
            continue
        item_key = str(item.get("dataset_key") or "")
        p = _dict(item.get("payload"))
        sc = _dict(p.get("source_config"))
        source_type = str(p.get("source_type") or sc.get("source_type") or "").lower()
        if not item_key:
            errors.append({"type": "missing_key", "message": "dataset_key가 없습니다."})
        if not source_type:
            errors.append({"type": "missing_source_type", "message": "payload.source_type이 없습니다.", "key": item_key})
        if source_type in {"oracle", "datalake"}:
            query = str(sc.get("query_template") or "")
            if not query:
                errors.append({"type": "missing_query_template", "message": "Oracle/Datalake dataset에는 query_template이 필요합니다.", "key": item_key})
            if any(marker in query.lower() for marker in TRUNCATED):
                errors.append({"type": "truncated_query", "message": "query_template이 축약되어 저장하지 않습니다.", "key": item_key})
        if source_type == "goodocs" and not sc.get("doc_id"):
            errors.append({"type": "missing_doc_id", "message": "Goodocs dataset에는 doc_id가 필요합니다.", "key": item_key})
        for field in sc:
            if str(field) not in ALLOWED_SOURCE_CONFIG_KEYS:
                errors.append({"type": "forbidden_source_config_key", "message": f"허용되지 않은 source_config 필드입니다: {field}", "key": item_key, "field": str(field)})
        errors.extend(_upstream_binding_errors(sc.get("upstream_bindings"), item_key))
        errors.extend(_metric_semantics_errors(p.get("metric_semantics"), item_key))
        errors.extend(_execution_column_contract_errors(p, item_key))
        for path in _secret_paths(item):
            errors.append({"type": "credential_field_forbidden", "message": f"credential/secret 필드는 저장할 수 없습니다: {path}", "key": item_key, "field": path})
    return _unique_errors(errors)


# 함수 설명: 실행 컬럼 계약은 filter_mappings의 canonical→실제 source 방향 하나로만 선언되도록 검증합니다.
def _execution_column_contract_errors(payload: dict[str, Any], item_key: str) -> list[dict[str, Any]]:
    declared_columns = _catalog_column_names(payload.get("columns"))
    declared_keys = {_column_key(column) for column in declared_columns}
    mappings = payload.get("filter_mappings")
    mappings = mappings if isinstance(mappings, dict) else {}
    errors: list[dict[str, Any]] = []
    alias_owners: dict[str, str] = {}
    canonical_keys = {
        _column_key(canonical)
        for canonical in mappings
        if str(canonical or "").strip()
    }
    for raw_canonical, raw_aliases in mappings.items():
        canonical = str(raw_canonical or "").strip()
        aliases = _string_list(raw_aliases)
        if not canonical or not aliases:
            errors.append({
                "type": "invalid_filter_mapping",
                "message": "filter_mappings는 canonical key와 하나 이상의 실제 source column을 가져야 합니다.",
                "key": item_key,
                "canonical_column": canonical,
            })
            continue
        for alias in aliases:
            alias_key = _column_key(alias)
            if declared_keys and alias_key not in declared_keys:
                errors.append({
                    "type": "filter_mapping_source_column_missing",
                    "message": f"filter_mappings 오른쪽 컬럼이 실제 조회 columns에 없습니다: {canonical} -> {alias}",
                    "key": item_key,
                    "canonical_column": canonical,
                    "source_column": alias,
                })
            owner = alias_owners.get(alias_key)
            if owner and _column_key(owner) != _column_key(canonical):
                errors.append({
                    "type": "ambiguous_execution_column_mapping",
                    "message": f"같은 실제 컬럼이 여러 canonical key에 연결되었습니다: {owner}, {canonical} -> {alias}",
                    "key": item_key,
                    "source_column": alias,
                })
            alias_owners.setdefault(alias_key, canonical)

    standard_aliases = payload.get("standard_column_aliases")
    if isinstance(standard_aliases, dict):
        for raw_business_key, raw_aliases in standard_aliases.items():
            business_key = str(raw_business_key or "").strip()
            for alias in _string_list(raw_aliases):
                owner = alias_owners.get(_column_key(alias))
                if owner and _column_key(owner) != _column_key(business_key):
                    errors.append({
                        "type": "business_alias_redefines_execution_column",
                        "message": f"standard_column_aliases가 실행 매핑을 다른 key로 재정의합니다: {business_key} -> {alias}, canonical={owner}",
                        "key": item_key,
                        "source_column": alias,
                    })

    semantics = payload.get("metric_semantics")
    if isinstance(semantics, dict):
        for metric in semantics:
            metric_key = _column_key(metric)
            if declared_keys and metric_key not in declared_keys and metric_key not in canonical_keys:
                errors.append({
                    "type": "metric_column_not_in_execution_schema",
                    "message": f"metric_semantics 컬럼이 실제 columns 또는 canonical filter_mappings에 없습니다: {metric}",
                    "key": item_key,
                    "metric": str(metric),
                })

    for column in _string_list(payload.get("default_detail_columns")):
        column_key = _column_key(column)
        if declared_keys and column_key not in declared_keys and column_key not in canonical_keys:
            errors.append({
                "type": "default_detail_column_not_in_execution_schema",
                "message": f"default_detail_columns 컬럼이 실제 columns 또는 canonical filter_mappings에 없습니다: {column}",
                "key": item_key,
                "column": column,
            })
    return errors


# 함수 설명: 다양한 columns 스키마에서 실제 조회 결과 컬럼명을 순서대로 추출합니다.
def _catalog_column_names(value: Any) -> list[str]:
    values = value if isinstance(value, list) else list(value) if isinstance(value, dict) else []
    result: list[str] = []
    for item in values:
        if isinstance(item, dict):
            item = item.get("column_name") or item.get("name") or item.get("column") or item.get("key")
        text = str(item or "").strip()
        if text and text not in result:
            result.append(text)
    return result


# 함수 설명: 단일 값 또는 배열을 공백 없는 중복 제거 문자열 목록으로 정규화합니다.
def _string_list(value: Any) -> list[str]:
    values = value if isinstance(value, (list, tuple, set)) else [value]
    result: list[str] = []
    for item in values:
        text = str(item or "").strip()
        if text and text not in result:
            result.append(text)
    return result


# 함수 설명: 대소문자와 구분문자 차이를 제거한 컬럼 비교 key를 생성합니다.
def _column_key(value: Any) -> str:
    return "".join(character for character in str(value or "").upper() if character.isalnum())


# 함수 설명: metric별 가산성·기본 집계 계약을 작은 허용 스키마로 검증합니다.
def _metric_semantics_errors(value: Any, item_key: str) -> list[dict[str, Any]]:
    if value in (None, "", {}):
        return []
    if not isinstance(value, dict):
        return [{
            "type": "invalid_metric_semantics",
            "message": "payload.metric_semantics는 metric 컬럼명을 key로 갖는 object여야 합니다.",
            "key": item_key,
        }]
    allowed_fields = {
        "semantic_type",
        "additive",
        "default_rollup",
        "allowed_rollups",
        "source_already_aggregated",
        "value_transform",
    }
    allowed_rollups = {"sum", "mean", "min", "max", "count", "nunique", "first", "last"}
    errors: list[dict[str, Any]] = []
    for metric, raw_contract in value.items():
        metric_name = str(metric or "").strip()
        location = {"key": item_key, "metric": metric_name}
        if not metric_name or not isinstance(raw_contract, dict):
            errors.append({
                "type": "invalid_metric_semantic_contract",
                "message": "metric_semantics의 각 metric 계약은 object여야 합니다.",
                **location,
            })
            continue
        for field in raw_contract:
            if str(field) not in allowed_fields:
                errors.append({
                    "type": "forbidden_metric_semantics_key",
                    "message": f"허용되지 않은 metric_semantics 필드입니다: {field}",
                    "field": str(field),
                    **location,
                })
        additive = raw_contract.get("additive")
        if additive is not None and not isinstance(additive, bool):
            errors.append({
                "type": "invalid_metric_additive_flag",
                "message": "metric_semantics.additive는 boolean이어야 합니다.",
                **location,
            })
        raw_rollups = raw_contract.get("allowed_rollups")
        values = raw_rollups if isinstance(raw_rollups, (list, tuple, set)) else [raw_rollups]
        rollups = [str(item).strip() for item in values if str(item or "").strip()]
        default_rollup = str(raw_contract.get("default_rollup") or "").strip().lower()
        invalid_rollups = [item for item in [default_rollup, *rollups] if item and item.lower() not in allowed_rollups]
        if invalid_rollups:
            errors.append({
                "type": "invalid_metric_rollup",
                "message": "지원하지 않는 metric 집계 방식이 있습니다: " + ", ".join(invalid_rollups),
                **location,
            })
        if additive is False and (
            default_rollup == "sum"
            or any(item.lower() == "sum" for item in rollups)
        ):
            errors.append({
                "type": "non_additive_metric_sum_forbidden",
                "message": "additive=false metric에는 sum 집계를 허용할 수 없습니다.",
                **location,
            })
        transform = raw_contract.get("value_transform")
        if transform not in (None, "", {}):
            if not isinstance(transform, dict):
                errors.append({
                    "type": "invalid_metric_value_transform",
                    "message": "metric_semantics.value_transform은 object여야 합니다.",
                    **location,
                })
            else:
                for field in transform:
                    if str(field) not in {"coerce_numeric", "multiplier"}:
                        errors.append({
                            "type": "forbidden_metric_value_transform_key",
                            "message": f"허용되지 않은 value_transform 필드입니다: {field}",
                            "field": str(field),
                            **location,
                        })
                if "coerce_numeric" in transform and not isinstance(transform.get("coerce_numeric"), bool):
                    errors.append({
                        "type": "invalid_metric_value_transform_coerce_numeric",
                        "message": "value_transform.coerce_numeric은 boolean이어야 합니다.",
                        **location,
                    })
                multiplier = transform.get("multiplier")
                valid_multiplier = not isinstance(multiplier, bool)
                if valid_multiplier:
                    try:
                        valid_multiplier = math.isfinite(float(multiplier))
                    except (TypeError, ValueError, OverflowError):
                        valid_multiplier = False
                if not valid_multiplier:
                    errors.append({
                        "type": "invalid_metric_value_transform_multiplier",
                        "message": "value_transform.multiplier는 유한한 숫자여야 합니다.",
                        **location,
                    })
    return errors


# 함수 설명: `_duplicate_lookup_errors()`는 05 조회기가 명시적으로 실패·건너뜀 경우 중복 정책 저장을 차단합니다.
def _duplicate_lookup_errors(payload: dict[str, Any], action: str) -> list[dict[str, Any]]:
    if action == "create_new":
        return []
    trace = _dict(payload.get("trace"))
    if "duplicate_lookup" not in trace:
        # 05 조회기를 거치지 않던 구버전 payload는 기존 호환성을 유지합니다.
        return []
    lookup = _dict(trace.get("duplicate_lookup"))
    lookup_status = str(lookup.get("status") or "").strip().lower()
    if lookup_status not in {"error", "skipped"}:
        return []
    return [
        {
            "type": "duplicate_lookup_unavailable",
            "message": "기존 테이블 카탈로그 동일 key 조회를 완료하지 못해 중복 여부를 확정할 수 없으므로 저장하지 않았습니다.",
            "lookup_status": lookup_status,
            "lookup_errors": deepcopy(_list(lookup.get("errors"))),
        }
    ]


# 함수 설명: `_upstream_binding_errors()`는 Flow 간 결과 전달에 쓰는 metadata binding을 추측 없이 실행 가능한 최소 스키마로 검증합니다.
def _upstream_binding_errors(value: Any, item_key: str) -> list[dict[str, Any]]:
    if value in (None, "", []):
        return []
    if not isinstance(value, list):
        return [{
            "type": "invalid_upstream_bindings",
            "message": "source_config.upstream_bindings는 object 목록이어야 합니다.",
            "key": item_key,
        }]

    errors: list[dict[str, Any]] = []
    seen_targets: set[str] = set()
    allowed_fields = {"entity_type", "source_alias", "source_column", "target_param", "operator", "max_values"}
    for index, binding in enumerate(value):
        location = {"key": item_key, "binding_index": index}
        if not isinstance(binding, dict):
            errors.append({
                "type": "invalid_upstream_binding",
                "message": "upstream_bindings의 각 항목은 object여야 합니다.",
                **location,
            })
            continue
        unknown = [str(field) for field in binding if str(field) not in allowed_fields]
        for field in unknown:
            errors.append({
                "type": "forbidden_upstream_binding_key",
                "message": f"허용되지 않은 upstream binding 필드입니다: {field}",
                "field": field,
                **location,
            })
        for field in ("entity_type", "source_column", "target_param"):
            if not str(binding.get(field) or "").strip():
                errors.append({
                    "type": "missing_upstream_binding_field",
                    "message": f"upstream binding 필수 필드가 없습니다: {field}",
                    "field": field,
                    **location,
                })
        source_alias = str(binding.get("source_alias") or "upstream_result").strip()
        if source_alias not in {"upstream_result", "previous_result"}:
            errors.append({
                "type": "unsupported_upstream_source_alias",
                "message": "upstream binding의 source_alias는 upstream_result 또는 previous_result만 지원합니다.",
                **location,
            })
        operator = str(binding.get("operator") or "in").strip().lower()
        if operator not in {"in", "eq"}:
            errors.append({
                "type": "unsupported_upstream_operator",
                "message": f"지원하지 않는 upstream binding operator입니다: {operator}",
                **location,
            })
        target_param = str(binding.get("target_param") or "").strip()
        target_marker = target_param.casefold()
        if target_marker and target_marker in seen_targets:
            errors.append({
                "type": "ambiguous_upstream_target_param",
                "message": f"같은 target_param이 둘 이상 선언되었습니다: {target_param}",
                **location,
            })
        if target_marker:
            seen_targets.add(target_marker)
        max_values = binding.get("max_values", 200)
        try:
            max_values_int = int(str(max_values).strip())
        except Exception:
            max_values_int = 0
        if not 1 <= max_values_int <= 10_000:
            errors.append({
                "type": "invalid_upstream_max_values",
                "message": "upstream binding max_values는 1~10000 정수여야 합니다.",
                **location,
            })
    return errors


# 함수 설명: `_merge_review()`는 결정론적 검증 결과와 선택적 추가 검수 결과를 하나의 저장 판단으로 합칩니다.
def _merge_review(llm_review: dict[str, Any], payload: dict[str, Any], deterministic_errors: list[dict[str, Any]]) -> dict[str, Any]:
    refinement = deepcopy(_dict(payload.get("refinement")))
    missing = [str(item).strip() for item in _list(refinement.get("missing_information")) if str(item or "").strip()]
    upstream_supplements = list(missing)
    if bool(refinement.get("needs_more_input")) and not upstream_supplements:
        upstream_supplements.append("저장에 필요한 정보를 원문에 보완해 주세요.")
    assumptions = [str(item).strip() for item in _list(refinement.get("assumptions")) if str(item or "").strip()]
    if not llm_review:
        errors = list(deterministic_errors)
        return {"ready_to_save": bool(payload.get("items")) and not errors and not upstream_supplements, "errors": errors, "supplement_requests": upstream_supplements, "assumptions": assumptions, "refinement": refinement}
    merged = deepcopy(llm_review)
    merged_errors = _list(merged.get("errors")) + deterministic_errors
    supplements = _unique_text_items(_list(merged.get("supplement_requests")) + upstream_supplements)
    merged["errors"] = _unique_errors(merged_errors)
    merged["supplement_requests"] = supplements
    merged["ready_to_save"] = bool(merged.get("ready_to_save")) and not merged["errors"] and not supplements and bool(payload.get("items"))
    merged["assumptions"] = _unique_text_items(_list(merged.get("assumptions")) + assumptions)
    merged["refinement"] = refinement
    return merged


# 함수 설명: `_unique_text_items()`는 문자열 또는 질문 dict 형태의 보완 요청을 순서를 유지하며 중복 제거합니다.
def _unique_text_items(values: list[Any]) -> list[Any]:
    result = []
    seen = set()
    for value in values:
        marker = json.dumps(value, ensure_ascii=False, sort_keys=True, default=str) if isinstance(value, dict) else str(value).strip()
        if marker and marker not in seen:
            seen.add(marker)
            result.append(deepcopy(value))
    return result


# 함수 설명: `_dry_run_result()`는 실제 DB를 변경하지 않고 실행 예정 작업만 보여 주는 dry-run 결과를 만듭니다.
def _dry_run_result(payload: dict[str, Any], action: str) -> dict[str, Any]:
    matched = _match_map(payload)
    operations = []
    for item in payload.get("items", []):
        key = str(_dict(item).get("dataset_key") or "")
        has_match = key.lower() in matched
        operation = "skipped" if has_match and action == "skip" else "create_new" if has_match and action == "create_new" else "merged" if has_match and action == "merge" else "replaced" if has_match else "inserted"
        operations.append({"key": key, "operation": operation})
    would_save = sum(1 for item in operations if item["operation"] != "skipped")
    return {"success": True, "ready_to_save": True, "dry_run": True, "saved_count": 0, "would_save_count": would_save, "skipped_count": len(operations) - would_save, "operation_by_key": operations, "message": "드라이런입니다. MongoDB에는 저장하지 않았습니다.", "keys": [item["key"] for item in operations]}


# 함수 설명: `_write_to_mongodb()`는 검증을 통과한 작업만 duplicate action에 맞춰 MongoDB에 저장하고 결과를 기록합니다.
def _write_to_mongodb(payload: dict[str, Any], action: str, mongo_uri: str, mongo_database: str, collection_name: str) -> dict[str, Any]:
    mongo_uri, mongo_database, collection_name = _resolve_mongo_config(mongo_uri, mongo_database, collection_name)
    if not mongo_uri or not mongo_database or not collection_name:
        return {"success": False, "ready_to_save": False, "saved_count": 0, "message": "MongoDB 저장 정보가 부족해 저장하지 않았습니다.", "errors": [{"type": "missing_mongo_config", "message": "mongo_uri, mongo_database, collection_name are required"}]}
    client = None
    operations = []
    try:
        client = getattr(import_module("pymongo"), "MongoClient")(mongo_uri, serverSelectionTimeoutMS=5000)
        collection = client[mongo_database][collection_name]
        now = datetime.now(timezone.utc).isoformat()
        raw_text = _redact_raw_text(str(_dict(payload.get("request")).get("raw_text") or ""))
        matched = _match_map(payload)
        for source_item in payload.get("items", []):
            item = deepcopy(source_item)
            key = str(item.get("dataset_key") or "")
            existing = deepcopy(matched.get(key.lower()) or collection.find_one({"_id": f"table_catalog:{key}"}) or {})
            if existing and action == "skip":
                operations.append({"key": key, "operation": "skipped"})
                continue
            if existing and action == "create_new":
                key = _next_key(collection, key)
                item["dataset_key"] = key
                existing = {}
                operation = "created_new"
            elif existing and action == "merge":
                item = _deep_merge(existing, item)
                item["dataset_key"] = key
                operation = "merged"
            elif existing:
                operation = "replaced"
            else:
                operation = "inserted"
            doc = deepcopy(item)
            doc["_id"] = f"table_catalog:{doc.get('dataset_key')}"
            if existing.get("created_at") and not doc.get("created_at"):
                doc["created_at"] = existing["created_at"]
            doc["updated_at"] = now
            if raw_text:
                doc["registration_trace"] = {"raw_text": raw_text}
            collection.replace_one({"_id": doc["_id"]}, doc, upsert=True)
            operations.append({"key": doc.get("dataset_key"), "operation": operation})
        saved_count = sum(1 for item in operations if item["operation"] != "skipped")
        skipped_count = len(operations) - saved_count
        return {"success": True, "ready_to_save": True, "status": "skipped" if not saved_count and skipped_count else "saved", "saved_count": saved_count, "skipped_count": skipped_count, "operation_by_key": operations, "database": mongo_database, "collection_name": collection_name, "message": "저장 처리를 완료했습니다.", "errors": []}
    except Exception as exc:
        saved_count = sum(1 for item in operations if item.get("operation") != "skipped")
        return {"success": False, "ready_to_save": False, "status": "partial_success" if saved_count else "error", "saved_count": saved_count, "partial_success": bool(saved_count), "operation_by_key": operations, "message": "MongoDB 저장 중 오류가 발생했습니다.", "errors": [{"type": "mongo_write_error", "message": str(exc)}]}
    finally:
        if client is not None:
            client.close()


# 함수 설명: `_match_map()`는 입력 조건과 일치하는 MAP을 찾아 비교·필터 결과로 반환합니다.
def _match_map(payload: dict[str, Any]) -> dict[str, dict[str, Any]]:
    result = {}
    for match in _list(payload.get("existing_matches")):
        match = _dict(match)
        key = str(match.get("existing_key") or match.get("new_key") or "").lower()
        existing = _dict(match.get("existing_item"))
        if key and existing:
            result[key] = existing
    return result


# 함수 설명: `_next_key()`는 create_new 정책에서 기존 key와 충돌하지 않는 다음 저장 key를 계산합니다.
def _next_key(collection: Any, key: str) -> str:
    base = f"{key}_copy"
    candidate = base
    index = 2
    while collection.find_one({"_id": f"table_catalog:{candidate}"}):
        candidate = f"{base}_{index}"
        index += 1
    return candidate


# 함수 설명: `_deep_merge()`는 중첩 dict를 재귀 병합하되 새 값이 지정된 필드만 기존 문서에 반영합니다.
def _deep_merge(existing: dict[str, Any], incoming: dict[str, Any]) -> dict[str, Any]:
    merged = deepcopy(existing)
    for key, value in incoming.items():
        if key == "_id":
            continue
        if isinstance(value, dict) and isinstance(merged.get(key), dict):
            merged[key] = _deep_merge(merged[key], value)
        else:
            merged[key] = deepcopy(value)
    return merged


# 함수 설명: `_secret_paths()`는 저장 후보 내부에서 password·token 등 비밀값으로 의심되는 필드 경로를 재귀 탐색합니다.
def _secret_paths(value: Any, prefix: str = "") -> list[str]:
    paths = []
    if isinstance(value, dict):
        for key, item in value.items():
            key_text = str(key)
            path = f"{prefix}.{key_text}" if prefix else key_text
            lowered = key_text.lower()
            if lowered not in SAFE_REFERENCE_KEYS and _is_secret_key(lowered):
                paths.append(path)
            else:
                paths.extend(_secret_paths(item, path))
    elif isinstance(value, list):
        for index, item in enumerate(value):
            paths.extend(_secret_paths(item, f"{prefix}[{index}]"))
    return paths


# 함수 설명: `_is_secret_key()`는 필드 이름이 credential·token·password 등 저장 금지 비밀 key인지 판정합니다.
def _is_secret_key(key: str) -> bool:
    normalized = re.sub(r"[^a-z0-9]+", "_", str(key or "").lower())
    return any(pattern in normalized for pattern in SECRET_PATTERNS)


# 함수 설명: `_redact_raw_text()`는 등록 원문에 포함될 수 있는 credential 값을 응답·trace에서 마스킹합니다.
def _redact_raw_text(value: str, limit: int = 2000) -> str:
    text = str(value or "")
    pattern = re.compile(r"(?i)(password|passwd|token|secret|api[_-]?key|authorization|credential)([\"']?\s*[:=]\s*[\"']?)([^\s,;\"'}]+)")
    return pattern.sub(r"\1\2***", text)[:limit]


# 함수 설명: `_duplicate_action()`는 요청에 지정된 skip/merge/replace/create_new 중복 처리 정책을 안전한 기본값과 함께 해석합니다.
def _duplicate_action(payload: dict[str, Any]) -> str:
    request = _dict(payload.get("request"))
    decision = _dict(payload.get("duplicate_decision"))
    action = str(request.get("duplicate_action") or decision.get("action") or "skip")
    return action if action in {"merge", "replace", "skip", "create_new"} else "skip"


# 함수 설명: `_resolve_mongo_config()`는 컴포넌트 입력→환경변수→기본값 순서로 MongoDB database와 collection 설정을 확정합니다.
def _resolve_mongo_config(mongo_uri: str = "", mongo_database: str = "", collection_name: str = "") -> tuple[str, str, str]:
    return (mongo_uri or os.getenv("MONGODB_URI", ""), mongo_database or os.getenv("MONGODB_DATABASE", DEFAULT_DATABASE), collection_name or os.getenv(COLLECTION_ENV, DEFAULT_COLLECTION))


# 함수 설명: `_unique_errors()`는 중복 오류 메시지를 최초 발생 순서대로 하나씩만 남깁니다.
def _unique_errors(errors: list[Any]) -> list[dict[str, Any]]:
    result = []
    seen = set()
    for error in errors:
        item = error if isinstance(error, dict) else {"type": "review_error", "message": str(error)}
        marker = (str(item.get("type")), str(item.get("field")), str(item.get("key")), str(item.get("message")))
        if marker not in seen:
            seen.add(marker)
            result.append(deepcopy(item))
    return result


# 함수 설명: `_payload()`는 Langflow Data/Message 또는 일반 dict 입력에서 안전한 dict 페이로드 복사본을 꺼냅니다.
def _payload(value: Any) -> dict[str, Any]:
    data = getattr(value, "data", value)
    return deepcopy(data) if isinstance(data, dict) else {}


# 함수 설명: `_json()`는 Message·dict·JSON 문자열에서 Markdown fence를 제거하고 JSON object를 안전하게 추출합니다.
def _json(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return deepcopy(value)
    text = str(getattr(value, "text", value) or "")
    match = re.search(r"```(?:json)?\s*(\{.*?\})\s*```", text, re.DOTALL)
    if match:
        text = match.group(1)
    try:
        parsed = json.loads(text)
    except Exception:
        return {}
    return parsed if isinstance(parsed, dict) else {}


# 함수 설명: `_dict()`는 입력값이 dict인지 확인하고 아니면 빈 dict를 반환해 후속 key 접근 오류를 막습니다.
def _dict(value: Any) -> dict[str, Any]:
    return value if isinstance(value, dict) else {}


# 함수 설명: `_list()`는 입력값을 list로 정규화하고 목록이 아닌 값은 안전한 기본 목록으로 바꿉니다.
def _list(value: Any) -> list[Any]:
    return value if isinstance(value, list) else []


# Langflow 컴포넌트 클래스: inputs/outputs가 캔버스 포트와 JSON edge 계약을 정의합니다.
# 실제 업무 규칙은 위의 주요 함수에 두어 UI 실행과 단위 테스트가 같은 로직을 사용합니다.
class TableCatalogReviewWriter(Component):
    display_name = "07 테이블 카탈로그 검수/저장 처리기"
    description = "스키마·credential·중복 action을 결정론적으로 검증한 뒤 드라이런 또는 MongoDB 저장을 실행합니다."
    inputs = [DataInput(name="payload", display_name="페이로드", required=True), MessageTextInput(name="mongo_uri", display_name="MongoDB 연결 URI", required=False, advanced=True), MessageTextInput(name="mongo_database", display_name="MongoDB 데이터베이스", required=False, value=DEFAULT_DATABASE, advanced=True), MessageTextInput(name="collection_name", display_name="컬렉션 이름", required=False, value=DEFAULT_COLLECTION, advanced=True)]
    outputs = [Output(name="payload_out", display_name="페이로드 출력", method="build_payload", types=["Data"])]

    # Langflow 출력 함수: '페이로드 출력 (payload_out)' 포트가 요청될 때 실행됩니다.
    # 핵심 처리 결과를 Langflow Data/Message 형식으로 감싸 다음 노드에 전달합니다.
    def build_payload(self) -> Data:
        return Data(data=review_and_write(getattr(self, "payload", None), "", getattr(self, "mongo_uri", ""), getattr(self, "mongo_database", ""), getattr(self, "collection_name", "")))

